import{_ as t,o as a,c as o,ag as d}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"二维定位解算器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/modules/position_solver_2d/index.md","filePath":"v0.3.0-alpha/modules/position_solver_2d/index.md"}'),r={name:"v0.3.0-alpha/modules/position_solver_2d/index.md"};function n(i,e,c,l,h,s){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="二维定位解算器" tabindex="-1">二维定位解算器 <a class="header-anchor" href="#二维定位解算器" aria-label="Permalink to &quot;二维定位解算器&quot;">​</a></h1><p>适用：v0.3.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>position_solver_2d</code> · 模块定义版本：1</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>根据到三个已知锚点的距离，求一个局部平面位置。模块将三个距离的平方两两相减，组成一个关于 x、y 的二元一次方程组，再从求得位置重算三个距离，输出距离残差 RMS。它是二维测距教学模型，不是 GNSS 或 RTK 解算器。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>测距模拟器.ranges → 二维定位解算器.ranges</code>。输入一个三分量距离 item，输出同一历元的两分量 <code>position=[x,y]</code> 和独立标量 <code>residual</code>，单位均为 m。</p><p>观察位置时，显式选择同一 <code>position</code> 的 0／1 分量作为 x／y，XY 按同时间基准和同原始时刻精确配对；残差单独观察，不能塞进位置向量当作第三维高度。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>ranges</code>（三锚点测距）</td><td><code>numeric_f64</code></td><td>m；vlen=3</td></tr><tr><td>输出</td><td><code>position</code>（二维位置）</td><td><code>numeric_f64</code></td><td>m；vlen=2</td></tr><tr><td>输出</td><td><code>residual</code>（测距 RMS 残差）</td><td><code>numeric_f64</code></td><td>m；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p><code>anchors_m</code> 的六项依次是 <code>[x1,y1,x2,y2,x3,y3]</code>，顺序必须对应输入距离的三个分量。解算器不会从上游自动复制站位，入门实验须核对两份设置。</p><p>重复、共线或几乎共线的锚点不能提供本模型要求的稳定二维约束，会在准备时被拒绝。参数范围和锚点约束见下表。</p><p><code>max_residual_m</code> 规定允许多大的距离残差。残差是“重算距离减输入距离”的三个差的均方根（RMS）：先平方、取平均，再开平方，单位 m，数值非负。该门限检查距离一致性，不承诺位置误差小于该值；本模块也不反复优化位置来寻找最小残差。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>三锚点坐标 [x1,y1,x2,y2,x3,y3] (m)<br><code>anchors_m</code></td><td><code>[0, 0, 10, 0, 0, 10]</code></td><td>按字段类型填写，见下文说明</td><td>重新准备</td></tr><tr><td>最大测距 RMS 残差 (m)<br><code>max_residual_m</code></td><td><code>1</code></td><td>范围 0 至 3.4028234663852886e+38</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>本模块不提供在线参数修改。停止、修改、重新准备后再运行；新参数不能追溯改写旧位置或旧残差。</p><p>负测距、无法得到有限位置或重算 RMS 超过门限时，任务会失败，保留最后有效数据及失败状态；不会补零、取绝对值或截负值伪造一个新位置。失败后仍看到旧点，不代表当前历元解算成功。</p><h2 id="示例与观察" tabindex="-1">示例与观察 <a class="header-anchor" href="#示例与观察" aria-label="Permalink to &quot;示例与观察&quot;">​</a></h2><h3 id="用三段距离解出平面坐标" tabindex="-1">用三段距离解出平面坐标 <a class="header-anchor" href="#用三段距离解出平面坐标" aria-label="Permalink to &quot;用三段距离解出平面坐标&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/01-position-from-ranges.cnsproj" download>下载 01-position-from-ranges.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 64 item；重新打开工程后需再次运行以取得数据。</p><p>用三段距离解出平面坐标</p><ul><li>静态位置 (3,4) m 的三距为 5、√65、√45 m；显式比较 x/y 分量，定位残差接近 0。</li></ul><p><a href="./../../learn/01-position-from-ranges/">三距定位课</a>使用锚点 <code>(0,0)</code>、<code>(10,0)</code>、<code>(0,10)</code> m。输入 <code>5、√65、√45 m</code> 时，手算位置为 <code>(3,4) m</code>，理想残差接近零。实际数据使用 Float32，不用显示小数的末位差异冒充定位误差结论。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>残差接近零，就证明真实位置准确吗？</strong> 不能。它只说明所得位置能解释这组三距离；锚点坐标、距离来源及真实位置仍需独立核验。</p><p><strong>为什么不能把三个距离随意交换？</strong> 每个分量对应一个确定锚点。交换距离却不交换相应锚点，会改变方程的物理含义。</p><p><strong>加噪声后偶尔失败，是否应把门限调得很大？</strong> 先检查输入距离、站位和实际失败原因。放大门限会放宽距离一致性要求，不能恢复被错误模型破坏的定位准确性。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/01-position-from-ranges/">10 三段距离求位置</a></li></ul>',32)])])}const _=t(r,[["render",n]]);export{m as __pageData,_ as default};
